    absolute_title:='가족친화·근로자 복지 인증'; end if;
  if absolute_title is null and title_text ~* '직무\s*발명\s*보상' then
    absolute_title:='직무발명보상 인증'; end if;
  if absolute_title is null and title_text ~* '표창|포상|유공자|시상식|수상\s*기업\s*선정' then
    absolute_title:='표창·포상·시상'; end if;
  if absolute_title is null and title_text ~* '안전보건|중대재해|산업안전|위생\s*관리|소방\s*(점검|안전)' then
    absolute_title:='안전·위생·규제 준수'; end if;
 if absolute_title is not null then
  return jsonb_build_object('relevance_status','OUT_OF_SCOPE','startup_leverage','LOW',
   'applicability','UNKNOWN','startup_leverage_reason',absolute_title,'restriction_summary',null); end if;
 -- Industry vocabulary is not itself an eligibility condition. Mirror the
 -- contextual audience/advisory checks in relevance._industry_restriction.
 for industry_field in 1..2 loop
  if industry_field=2 and applicant_text ~* '(?:분야|산업|업종)\s*(?:무관|제한\s*없)|모든\s*분야|전\s*분야' then continue; end if;
  foreach industry_sentence in array regexp_split_to_array(
   (array[applicant_text,title_text])[industry_field],'[\n.!?。,;；]+|(?:하며|이며|이고)\s+') loop
   if industry_sentence ~* '(?:제한|관계|상관)\s*(?:은|이|가|없음|없이)*\s*없|무관|권장|권고|적합성.{0,25}검토|예시|가령' then continue; end if;
   for industry_hit in select regexp_matches(industry_sentence,
    '((?:바이오|헬스\s*케어|의료\s*기기|제약|반도체|이차\s*전지|배터리|소재\s*부품\s*장비|소부장|디스플레이|조선|자동차\s*부품|방위\s*산업|우주\s*항공|농업|수산|축산|식품\s*산업|화학\s*산업|섬유|뿌리\s*산업|관광|콘텐츠\s*산업)(?!\s*(?:대학교|대학|공사|재단|진흥원|센터|연구원)))(.{0,100})','gi') loop
    if industry_hit[2] ~* '분야|산업|업종|스타트업|창업\s*(?:기업|팀|자)|기업|업체|팀' then
     industry_restricted:=true; exit;
    end if;
   end loop;
   exit when industry_restricted;
  end loop;
  exit when industry_restricted;
 end loop;
 if industry_restricted then restriction:=array['특정 산업 분야 한정'::text]; end if;
 foreach eligibility_sentence in array regexp_split_to_array(applicant_text,'[\n.!?。,;；]+|(?:하며|이며|이고)\s+') loop
  if eligibility_sentence ~* '필수\s*(?:가\s*)?(?:아니|아님)|불필요|필요\s*없|무관|제한\s*없|우대|가점|권장|권고' then continue; end if;
  if eligibility_sentence ~* '사업자\s*등록(증|자)?\s*(보유|필수|필요|기업)|법인\s*(설립|사업자)\s*(필수|필요|보유)|중소기업\s*확인서' and not restriction @> array['사업자등록·법인 필요'::text] then
    restriction:=restriction||'사업자등록·법인 필요'::text; end if;
  if eligibility_sentence ~* '\yPre-?\s*A\y|\ySeries\s*[A-C]\y|시리즈\s*[A-C]|프리\s*에이|엔젤\s*(?:이상)?[^\n]{0,15}투자\s*유치' and not restriction @> array['투자 단계 한정'::text] then
    restriction:=restriction||'투자 단계 한정'::text; end if;
  if eligibility_sentence ~* '(?:업력|설립|창업)\s*\d+\s*년\s*이상' and not restriction @> array['업력 하한 조건'::text] then
    restriction:=restriction||'업력 하한 조건'::text; end if;
  if eligibility_sentence ~* '수출\s*실적|수출\s*\d+\s*(만|억)' and not restriction @> array['수출 실적 요건'::text] then
    restriction:=restriction||'수출 실적 요건'::text; end if;
  if eligibility_sentence ~* '(?:본사|기업|사업장)\s*이전\s*(?:필수|필요|조건)|(?:관내\s*)?이전\s*조건' and not restriction @> array['소재지 이전 필요'::text] then
    restriction:=restriction||'소재지 이전 필요'::text; end if;
  if eligibility_sentence ~* '만\s*(?:[4-9]\d)\s*세\s*이상|중장년\s*(?:예비)?\s*창업' and not restriction @> array['중장년 연령 조건'::text] then
    restriction:=restriction||'중장년 연령 조건'::text; end if;
  if eligibility_sentence ~* '프로토타입\s*이상[^\n]{0,15}(?:제품|개발)|(?:MVP|시제품)\s*보유\s*(?:필수|필요)' and not restriction @> array['프로토타입 이상 제품 필요'::text] then
    restriction:=restriction||'프로토타입 이상 제품 필요'::text; end if;
 end loop;
 foreach eligibility_sentence in array regexp_split_to_array(applicant_text,'[\n.!?。,;；]+|(?:하며|이며|이고)\s+') loop
  if eligibility_sentence ~* '가점|우대|우선|지역\s*(?:무관|제한\s*없)|소재지\s*무관' then continue; end if;
  region_hit:=regexp_match(eligibility_sentence,'((?:서울(?:특별시)?|부산(?:광역시)?|대구(?:광역시)?|인천(?:광역시)?|광주(?:광역시)?|대전(?:광역시)?|울산(?:광역시)?|세종(?:특별자치시)?|경기(?:도)?|강원(?:특별자치도|도)?|충북|충남|전북(?:특별자치도)?|전남|경북|경남|제주(?:특별자치도|도)?|충청북도|충청남도|전라북도|전라남도|경상북도|경상남도|[가-힣]{2,6}(?:특별자치[시도]|특별시|광역시|도|시|군|구)))\s*(?:에|내|의)?\s*(소재|거주)');
  if region_hit is null then region_hit:=regexp_match(eligibility_sentence,'((?:서울(?:특별시)?|부산(?:광역시)?|대구(?:광역시)?|인천(?:광역시)?|광주(?:광역시)?|대전(?:광역시)?|울산(?:광역시)?|세종(?:특별자치시)?|경기(?:도)?|강원(?:특별자치도|도)?|충북|충남|전북(?:특별자치도)?|전남|경북|경남|제주(?:특별자치도|도)?|충청북도|충청남도|전라북도|전라남도|경상북도|경상남도|[가-힣]{2,6}(?:특별자치[시도]|특별시|광역시|도|시|군|구)))\s*(?:내|에|로)?\s*(?:창업|설립|이전)\s*예정'); end if;
  if region_hit is null and not eligibility_sentence ~* '(?:관내|도내|시내)\s*(?:에\s*)?소재|(?:관내|도내|시내)\s*(?:기업|업체|법인)' then continue; end if;
  region:=coalesce(region_hit[1],(regexp_match(title_text,'^\s*[\[【]\s*(서울(?:특별시)?|부산(?:광역시)?|대구(?:광역시)?|인천(?:광역시)?|광주(?:광역시)?|대전(?:광역시)?|울산(?:광역시)?|세종(?:특별자치시)?|경기(?:도)?|강원(?:특별자치도|도)?|충북|충남|전북(?:특별자치도)?|전남|경북|경남|제주(?:특별자치도|도)?|충청북도|충청남도|전라북도|전라남도|경상북도|경상남도)\s*[\]】]'))[1]);
  if region is null then region_summary:='주관지역 소재 조건';
  elsif applicant_text ~* '이전\s*(?:예정|가능|계획)|설립\s*예정|창업\s*예정' then region_summary:=region||' 소재·이전·창업 예정 조건';
  elsif region_hit is not null and eligibility_sentence ~* '((?:서울(?:특별시)?|부산(?:광역시)?|대구(?:광역시)?|인천(?:광역시)?|광주(?:광역시)?|대전(?:광역시)?|울산(?:광역시)?|세종(?:특별자치시)?|경기(?:도)?|강원(?:특별자치도|도)?|충북|충남|전북(?:특별자치도)?|전남|경북|경남|제주(?:특별자치도|도)?|충청북도|충청남도|전라북도|전라남도|경상북도|경상남도|[가-힣]{2,6}(?:특별자치[시도]|특별시|광역시|도|시|군|구)))\s*(?:에|내|의)?\s*(소재|거주)' and region_hit[2]='거주' then region_summary:=region||' 거주 조건';
  elsif applicant_text ~* '예비\s*창업|개인|거주|청년|학생' then region_summary:=region||' 지역 조건';
  else region_summary:=region||' 소재 기업'; end if;
  restriction:=restriction||region_summary; exit;
 end loop;
 restriction_summary:=nullif(left(array_to_string(restriction,' · '),200),'');
 if hard is not null and cardinality(core)>0 and startup_candidate then
  return jsonb_build_object('relevance_status','REVIEW_REQUIRED','startup_leverage','UNKNOWN',
   'applicability','UNKNOWN','startup_leverage_reason','지원 내용에 서로 다른 신호가 있어 원문 확인 필요',
   'restriction_summary',restriction_summary); end if;
 if hard is not null then
  return jsonb_build_object('relevance_status','OUT_OF_SCOPE','startup_leverage','LOW',
   'applicability','UNKNOWN','startup_leverage_reason',hard,'restriction_summary',null); end if;
  if generic is null and t ~* '판로\s*(개척|지원)|전시회\s*참가|박람회\s*참가|시장\s*개척단|무역\s*사절단|수출\s*바우처|해외\s*규격\s*인증' then
    generic:='일반 판로·전시 참가 지원'; end if;
  if generic is null and t ~* '(규격|시험|성적서|경영|품질)\s*인증|인증\s*획득|일반\s*컨설팅|경영\s*컨설팅' then
    generic:='일반 인증·컨설팅 지원'; end if;
  if generic is null and t ~* '교육생\s*모집|직무\s*교육|장비\s*교육|역량\s*강화\s*교육|아카데미\s*수강' then
    generic:='일반 교육 과정'; end if;
  if event is null and t ~* '특강|강연|세미나|설명회|간담회|컨퍼런스|포럼|네트워킹|밋업|커피챗|토크\s*콘서트|워크숍' then
    event:='일회성 강연·행사'; end if;
  if event is null and t ~* '성공\s*(사례|스토리)|(?:참여|수강|활동|창업|운영)\s*후기|후기\s*(공유|모음|작성|발표|나눔)|(?<![가-힣A-Za-z0-9])후기(?![가-힣A-Za-z0-9])|이야기|경험\s*공유' then
    event:='사례·후기 공유'; end if;
  if deliverable is null and t ~* '\yMVP\y|프로토타입|시제품|시작품' then
    deliverable:='MVP·프로토타입 결과물'; end if;
  if deliverable is null and t ~* '\yPoC\y|실증|테스트\s*베드' then
    deliverable:='실증·PoC 수행'; end if;
  if deliverable is null and t ~* '데모\s*데이|demo\s*day|(?<![A-Za-z0-9])IR\s*(피칭|덱|자료|발표)|투자\s*(매칭|연계|검토)' then
    deliverable:='IR·데모데이 선발'; end if;
  if deliverable is null and t ~* '액셀러레이[팅터][^\n]{0,25}(선발|선정|성장\s*프로그램)|(?:선정|선발)[^\n]{0,25}액셀러레이팅|배치\s*(프로그램|선발)|accelerat' then
    deliverable:='액셀러레이팅 선발'; end if;
  if deliverable is null and t ~* '사업화\s*(지원|자금)|상용화' then
    deliverable:='사업화·상용화 지원'; end if;
  if deliverable is null and t ~* '고객\s*(발굴|검증|인터뷰)|시장\s*검증|\yBM\y\s*검증|비즈니스\s*모델\s*검증' then
    deliverable:='고객·시장 검증 수행'; end if;
  if deliverable is null and t ~* '창업(?:가|팀)[^\n]{0,20}피어\s*피드백' then
    deliverable:='창업 실행 피어피드백'; end if;
 if event is not null and deliverable is null then
  return jsonb_build_object('relevance_status','OUT_OF_SCOPE','startup_leverage','LOW',
   'applicability','UNKNOWN','startup_leverage_reason',event,'restriction_summary',null); end if;
 if generic is not null and cardinality(core)=0 then
  return jsonb_build_object('relevance_status','OUT_OF_SCOPE','startup_leverage','LOW',
   'applicability','UNKNOWN','startup_leverage_reason',generic,'restriction_summary',null); end if;
 if cardinality(core)=0 then
  if startup_candidate then
   return jsonb_build_object('relevance_status','REVIEW_REQUIRED','startup_leverage','UNKNOWN',
    'applicability','UNKNOWN','startup_leverage_reason','창업 관련 공고이나 구체적인 지원 내용 확인 필요',
    'restriction_summary',restriction_summary); end if;
  return jsonb_build_object('relevance_status','OUT_OF_SCOPE','startup_leverage','LOW',
   'applicability','UNKNOWN','startup_leverage_reason','창업 실행 레버리지 근거 없음',
   'restriction_summary',null); end if;
 if cardinality(restriction)=0 then
  return jsonb_build_object('relevance_status','GFC_RELEVANT','startup_leverage','HIGH',
   'applicability','BROAD','startup_leverage_reason',core_reason,'restriction_summary',null); end if;
 restriction_summary:=left(array_to_string(restriction,' · '),200);
 return jsonb_build_object('relevance_status','CONDITIONAL','startup_leverage','HIGH',
  'applicability','RESTRICTED','startup_leverage_reason',core_reason,
  'restriction_summary',restriction_summary);
end $fn$;
revoke all on function startup_radar.gfc_relevance_v1_3(text,text,text) from public,anon,authenticated;
grant execute on function startup_radar.gfc_relevance_v1_3(text,text,text) to service_role;
